window.docContents[14].resolve({"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Finding-Loop-Invariants--Exercise___-Slow-Assignment":{"contents":"\n\nA roundabout way of assigning a number currently stored in X to\nthe variable Y is to start Y at 0, then decrement X until\nit hits 0, incrementing Y at each step. Here is a program that\nimplements this idea.  Fill in decorations and prove the decorated\nprogram correct. (The proof should be very simple.)def slowAssignmentDec (m : Nat) : Decorated where\n  pre := ({{ X = m }})\n  body := dcom {\n    Y := 0 {{ solution!({{ X = m ∧ Y = 0 }}) }};\n    (->> {{ solution!({{ Y + X = m }}) }}\n      while (X ≠ 0) do\n        {{ solution!({{ Y + X = m ∧ ¬ X = 0 }}) }}\n        ->> {{ solution!({{ Y + (X - 1) + 1 = m }}) }}\n        X := X - 1 {{ solution!({{ Y + X + 1 = m }}) }};\n        (->> {{ solution!({{ Y + X + 1 = m }}) }}\n          Y := Y + 1 {{ solution!({{ Y + X = m }}) }})\n      end\n        {{ solution!({{ Y + X = m ∧ X = 0 }}) }}\n      ->> {{ Y = m }})\n  }\n\ntheorem slow_assignment (m : Nat) :\n    (slowAssignmentDec m).OuterTripleValid := by\n  solution!\n    sorry\n\n\n","context":"Hoare Logic\u0009Hoare2: Hoare Logic, Part II\u0009Finding Loop Invariants","header":"6.3.2. Exercise: Slow Assignment","id":"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Finding-Loop-Invariants--Exercise___-Slow-Assignment"}});